// WRONG: Character-based estimation
estimated_tokens = len(text) / 4  // Unreliable, 20-30% error

// CORRECT: Official tokenizer
import tiktoken
encoder = tiktoken.encoding_for_model("gpt-4")
actual_tokens = len(encoder.encode(text))  // Accurate

// EXPENSIVE (verbose):
"Please provide me with a comprehensive and detailed analysis..."
// 12 tokens

// OPTIMIZED (concise):
"Analyze this in detail:"
// 5 tokens (58% reduction)
